package svm_escrow_encoding

import (
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"runtime"
	"sync"
)

// TestVectors holds the message_prehash pipeline vector loaded from
// testdata/test_vectors.json (generated by the sibling
// typescript/scripts/generate-test-vectors.mjs).
//
// SCOPE: this file is now ONLY the determine_payment_id pipeline check (Go's
// JSON parse + Base58 decode -> deposit_hash). The deposit / reserve / release /
// refund hash spec is validated against the program-sourced
// ../../parity-golden.json (see parity_golden_test.go), not this file.
type TestVectors struct {
	Domain             DomainVector             `json:"domain"`
	DeterminePaymentID DeterminePaymentIDVector `json:"determine_payment_id"`
}

// DomainVector captures the fixed test hash domain (ProtocolConfig fields +
// program ID) used by the message_prehash pipeline vector.
type DomainVector struct {
	ClusterID              string `json:"cluster_id"`
	SignatureDomainVersion uint8  `json:"signature_domain_version"`
	ProgramID              string `json:"program_id"`
}

// DeterminePaymentIDVector tests the full end-to-end pipeline:
// message_prehash JSON (Base58 pubkeys, hex deposit_request_hash, string amounts) → deposit_hash
// This validates that Go's JSON parsing + Base58 decoding matches JavaScript's encoding.
type DeterminePaymentIDVector struct {
	// MessagePrehash is the JSON string containing deposit params in real-world formats
	MessagePrehash string `json:"message_prehash"`
	ExpectedHash   string `json:"expected_hash"`
}

var (
	testVectors     *TestVectors
	testVectorsOnce sync.Once
	testVectorsErr  error
)

// loadTestVectors loads the test vectors from the JSON file.
// It uses sync.Once to ensure the file is only read once across all tests.
func loadTestVectors() (*TestVectors, error) {
	testVectorsOnce.Do(func() {
		// Get the directory of this test file
		_, filename, _, ok := runtime.Caller(0)
		if !ok {
			testVectorsErr = os.ErrNotExist
			return
		}

		testdataPath := filepath.Join(filepath.Dir(filename), "testdata", "test_vectors.json")
		data, err := os.ReadFile(testdataPath)
		if err != nil {
			testVectorsErr = err
			return
		}

		var vectors TestVectors
		if err := json.Unmarshal(data, &vectors); err != nil {
			testVectorsErr = err
			return
		}

		testVectors = &vectors
	})

	return testVectors, testVectorsErr
}

// createFilledBytes32 creates a 32-byte value filled with the given byte.
func createFilledBytes32(fill byte) [32]byte {
	var id [32]byte
	for i := range id {
		id[i] = fill
	}
	return id
}

// createFilledPubkey creates a 32-byte pubkey filled with the given byte
func createFilledPubkey(fill byte) Pubkey {
	var pk Pubkey
	for i := range pk {
		pk[i] = fill
	}
	return pk
}

// hexToBytes32 converts a hex string to a [32]byte array.
// Panics if the hex string is invalid or wrong length (for use in tests only).
func hexToBytes32(hexStr string) [32]byte {
	decoded, err := hex.DecodeString(hexStr)
	if err != nil {
		panic("hexToBytes32: invalid hex: " + err.Error())
	}
	if len(decoded) != 32 {
		panic("hexToBytes32: expected 32 bytes")
	}
	var result [32]byte
	copy(result[:], decoded)
	return result
}

// testEscrowDomain returns the fixed test EscrowDomain used by unit tests in
// this package. It MUST stay in lock-step with the `domain` block in
// testdata/test_vectors.json (regenerate via
// the sibling typescript/scripts/generate-test-vectors.mjs).
func testEscrowDomain() EscrowDomain {
	var clusterID [32]byte
	copy(clusterID[:], []byte("test"))
	return EscrowDomain{
		ClusterID:              clusterID,
		SignatureDomainVersion: 1,
		ProgramID:              createFilledPubkey(0xAB),
	}
}

// testDestination is the ratified canonical destination form: `<CAIP-19 asset>@<account>`, lowercase
// throughout for an eip155 namespace. 103 bytes, comfortably inside MaxDestinationLen and the
// ~152-byte legacy-transaction ceiling. Its keccak is byte-identical to what EVM commits for the same
// string, which is what makes the commitment comparable across chains.
const testDestination = "eip155:8453/erc20:0x833589fcd6edb6e08f4c7c32d4f71b54bda02913@0xc0ffee254729296a45a3885639ac7e10f9d54979"
